//! 🔀️ Original transition fields retain their real native owners under the original caller ledger and paid receiving grants.
use semio_framework_value::native_decoding::NativeDecodeCloseControl;
use super::{HistoryTransitionRecord,RetainedHistoryIdDecode,RetainedHistoryRecords,RetainedHistoryRecordsStep};
use protocol::{codec::{RetainedWireByteSource,OriginalWireSourceIdentity,HistoryReadLimits,RetainedWireFieldDecode},dictionary::RetainedSourceDictionary};
use semio_framework_value::{SharedUtf8,NativeDecodeControl,ValueError,ValueRefusalKind,RetainedCloneGrant,RetainedCloneProgress,RetirementDemand};
use std::mem::ManuallyDrop;
#[derive(semio_framework_value::RetireOwned)]
pub struct RetainedHistoryTransitionPartial{pub id:Option<String>,pub actor_text:Option<String>,pub actor:Option<SharedUtf8>,pub hlt:Option<(u64,u64,u64)>,pub dependencies:Option<Vec<String>>,pub pending_dependency:Option<String>,pub payload:Option<Vec<u8>>,pub observed:Option<String>}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum RetainedHistoryTransitionStep{Blocked,Progress,Ready,Fault,Closed}
#[doc(hidden)] pub struct RetainedHistoryTransitionDecode{source:OriginalWireSourceIdentity,control_identity:(u64,Option<u64>),limits:HistoryReadLimits,end:usize,position:usize,#[doc(hidden)] pub phase:u8,next_phase:u8,id_target:u8,format:u8,remaining:usize,closing:bool,closed:bool,partial:ManuallyDrop<Option<RetainedHistoryTransitionPartial>>,id:ManuallyDrop<Option<RetainedHistoryIdDecode>>,dependencies:ManuallyDrop<Option<RetainedHistoryRecords<String>>>,field:ManuallyDrop<Option<RetainedWireFieldDecode>>,fault:ManuallyDrop<Option<ValueError>>,receipt:Option<(RetainedCloneGrant,RetainedCloneProgress)>}
fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn metadata()->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->Result<RetirementDemand,ValueError>{d.depth=d.depth.checked_add(1).ok_or_else(||fault("original transition depth overflows"))?;Ok(d)}
fn permits(g:RetainedCloneGrant,d:RetirementDemand)->bool{g.maximum_items>0&&g.maximum_depth>=d.depth&&g.maximum_copy_bytes>=d.copy_bytes&&g.maximum_capacity_bytes>=d.capacity_bytes&&g.maximum_release_bytes>=d.release_bytes}
fn scalar<S:RetainedWireByteSource+?Sized>(source:&S,position:&mut usize,end:usize)->Result<u64,ValueError>{let mut result=0;for index in 0..10{let byte=source.byte_at(*position).filter(|_|*position<end).ok_or_else(||fault("original transition scalar is truncated"))?;if index==9&&byte>1{return Err(fault("original transition scalar overflows"))}*position+=1;result|=u64::from(byte&127)<<(index*7);if byte&128==0{return Ok(result)}}Err(fault("original transition scalar is unbounded"))}
impl RetainedHistoryTransitionDecode{
 pub fn admit<S:RetainedWireByteSource+?Sized>(source:&S,range:(usize,usize),limits:HistoryReadLimits,control:&NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<Option<Self>,ValueError>{limits.validate()?;let identity=source.original_source_identity();if range.0>range.1||range.1>identity.extent||range.1-range.0>limits.frame_body_bytes as usize||identity.extent>limits.file_bytes as usize{return Err(fault("original transition exceeds declared source policy"))}if g.maximum_items==0||g.maximum_depth<2{return Ok(None)}Ok(Some(Self{source:identity,control_identity:(control.ledger_identity(),control.retirement_recipient_identity()),limits,end:range.1,position:range.0,phase:0,next_phase:0,id_target:0,format:0,remaining:0,closing:false,closed:false,partial:ManuallyDrop::new(Some(RetainedHistoryTransitionPartial{id:None,actor_text:None,actor:None,hlt:None,dependencies:None,pending_dependency:None,payload:None,observed:None})),id:ManuallyDrop::new(None),dependencies:ManuallyDrop::new(None),field:ManuallyDrop::new(None),fault:ManuallyDrop::new(None),receipt:Some((g,metadata()))}))}
 fn validate<S:RetainedWireByteSource+?Sized>(&self,source:&S,control:&dyn NativeDecodeCloseControl)->Result<(),ValueError>{if self.source!=source.original_source_identity()||self.control_identity!=(control.ledger_identity(),control.retirement_recipient_identity()){return Err(fault("original transition changed source or receiving owner"))}Ok(())}
 fn publish(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.receipt=Some((g,p));if !p.fits(g){return Err(fault("original transition exceeded caller grant").with_retained_progress(p))}Ok(())}
 fn accept(&mut self,g:RetainedCloneGrant,child:RetainedCloneGrant,receipt:Option<(RetainedCloneGrant,RetainedCloneProgress)>)->Result<RetainedHistoryTransitionStep,ValueError>{let Some((issued,p))=receipt else{return Ok(RetainedHistoryTransitionStep::Blocked)};if issued!=child{return Err(fault("original transition child changed grant"))}self.publish(g,p)?;Ok(RetainedHistoryTransitionStep::Progress)}
 pub fn receipt(&self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt}
 pub fn take_receipt(&mut self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt.take()}
 pub fn source_identity(&self)->OriginalWireSourceIdentity{self.source}
 pub fn consumed_end(&self)->usize{self.position}
 pub fn fault(&self)->Option<&ValueError>{self.fault.as_ref()}
 pub fn is_ready(&self)->bool{self.phase==13&&!self.closed&&!self.closing&&self.receipt.is_none()&&self.id.is_none()&&self.field.is_none()&&self.dependencies.is_none()&&self.fault.is_none()}
 pub fn demands<S:RetainedWireByteSource+?Sized>(&self,source:&S,control:&dyn NativeDecodeCloseControl,body:usize)->Result<RetirementDemand,ValueError>{self.validate(source,control)?;if self.receipt.is_some()||self.closed{return Ok(Default::default())}if let Some(id)=self.id.as_ref(){return nested(id.demands(source,&[],body)?)}if let Some(field)=self.field.as_ref(){return nested(if self.closing{field.close_demands()}else{field.demands(source,body)?})}if self.closing{return Ok(RetirementDemand{depth:if self.dependencies.is_some(){2}else{1},..Default::default()})}if self.phase==4{return nested(SharedUtf8::admission_demand())}if self.phase==8{return nested(self.dependencies.as_ref().unwrap().demands()?)}Ok(RetirementDemand{depth:if matches!(self.phase,1|2|6|7|12){3}else if self.phase==9{2}else{1},..Default::default()})}
 fn start_id<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,dictionary:&RetainedSourceDictionary,target:u8,next:u8,g:RetainedCloneGrant)->Result<RetainedHistoryTransitionStep,ValueError>{let child=RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g};let Some(mut id)=RetainedHistoryIdDecode::admit(source,(self.position,self.end),dictionary,&[],child)?else{return Ok(RetainedHistoryTransitionStep::Blocked)};self.position=id.consumed_end();self.id_target=target;self.next_phase=next;let too_large=id.output_bytes()>self.limits.maximum_text_bytes as usize;let receipt=id.take_receipt();*self.id=Some(id);let status=self.accept(g,child,receipt)?;if too_large{return Err(fault("original transition identifier exceeds declared text limit"))}Ok(status)}
 pub fn step<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,dictionary:&RetainedSourceDictionary,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedHistoryTransitionStep,ValueError>{self.validate(source,control)?;if self.receipt.is_some()||self.closing||self.closed{return Ok(RetainedHistoryTransitionStep::Blocked)}if self.fault.is_some(){return Ok(RetainedHistoryTransitionStep::Fault)}if self.is_ready(){return Ok(RetainedHistoryTransitionStep::Ready)}let d=self.demands(source,control,g.maximum_copy_bytes)?;if !permits(g,d){return Ok(RetainedHistoryTransitionStep::Blocked)}control.checkpoint()?;match self.step_inner(source,dictionary,control,g){Ok(status)=>Ok(status),Err(error)=>{*self.fault=Some(error);if self.receipt.is_none(){self.publish(g,metadata())?}Ok(RetainedHistoryTransitionStep::Fault)}}}
 fn step_inner<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,dictionary:&RetainedSourceDictionary,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedHistoryTransitionStep,ValueError>{
  let child=RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g};
  if self.id.is_some(){if self.id.as_ref().unwrap().terminal_is_empty(){drop(self.id.take());self.phase=self.next_phase;self.publish(g,metadata())?;return Ok(RetainedHistoryTransitionStep::Progress)}let id=self.id.as_mut().unwrap();control.charge(id.demands(source,&[],child.maximum_copy_bytes)?.capacity_bytes)?;let partial=self.partial.as_mut().unwrap();let slot=match self.id_target{0=>&mut partial.id,1=>&mut partial.actor_text,2=>&mut partial.pending_dependency,_=>&mut partial.observed};let result=if id.is_ready(){id.take_ready_into(source,&[],slot,child)}else{id.step(source,&[],child)};let receipt=id.take_receipt();let status=self.accept(g,child,receipt)?;result?;return Ok(status)}
  if self.field.is_some(){if self.field.as_ref().unwrap().terminal_is_empty(){drop(self.field.take());self.phase=12;self.publish(g,metadata())?;return Ok(RetainedHistoryTransitionStep::Progress)}let field=self.field.as_mut().unwrap();control.charge(field.demands(source,child.maximum_copy_bytes)?.capacity_bytes)?;let result=if field.is_ready(){field.take_into(&mut self.partial.as_mut().unwrap().payload,child)}else{field.advance(source,child)};let receipt=field.take_receipt();let status=self.accept(g,child,receipt)?;result?;return Ok(status)}
  match self.phase{
   0=>{let format=source.byte_at(self.position).filter(|_|self.position<self.end).ok_or_else(||fault("original transition format is absent"))?;if !(1..=2).contains(&format){return Err(fault("original transition format is invalid"))}self.format=format;self.position+=1;self.phase=1},
   1=>return self.start_id(source,dictionary,0,2,g),2=>return self.start_id(source,dictionary,1,4,g),
   4=>{control.charge(SharedUtf8::admission_demand().capacity_bytes)?;let original=self.partial.as_mut().unwrap().actor_text.take().unwrap();match SharedUtf8::admit(original,child){Ok((actor,p))=>{self.partial.as_mut().unwrap().actor=Some(actor);self.phase=5;self.publish(g,p)?;return Ok(RetainedHistoryTransitionStep::Progress)},Err((error,original))=>{self.partial.as_mut().unwrap().actor_text=Some(original);return Err(error)}}},
   5=>{let mut position=self.position;let hlt=(scalar(source,&mut position,self.end)?,scalar(source,&mut position,self.end)?,scalar(source,&mut position,self.end)?);self.partial.as_mut().unwrap().hlt=Some(hlt);let count=usize::try_from(scalar(source,&mut position,self.end)?).map_err(|_|fault("original transition dependency count exceeds platform"))?;if count>self.limits.maximum_fields as usize{return Err(fault("original transition dependencies exceed declared fields"))}self.position=position;self.remaining=count;self.phase=6},
   6=>{let Some(mut records)=RetainedHistoryRecords::admit(child)?else{return Ok(RetainedHistoryTransitionStep::Blocked)};let receipt=records.take_receipt();*self.dependencies=Some(records);self.phase=7;return self.accept(g,child,receipt)},
   7 if self.remaining>0=>return self.start_id(source,dictionary,2,8,g),
   7=>{let result=self.dependencies.as_mut().unwrap().take_ready_into(&mut self.partial.as_mut().unwrap().dependencies,child);let receipt=self.dependencies.as_mut().unwrap().take_receipt();let status=self.accept(g,child,receipt)?;result?;self.phase=9;return Ok(status)},
   8=>{control.charge(self.dependencies.as_ref().unwrap().demands()?.capacity_bytes)?;let result=self.dependencies.as_mut().unwrap().append_original(&mut self.partial.as_mut().unwrap().pending_dependency,child);let receipt=self.dependencies.as_mut().unwrap().take_receipt();let status=self.accept(g,child,receipt)?;if result?==RetainedHistoryRecordsStep::Published{self.remaining-=1;self.phase=7}return Ok(status)},
   9=>{if self.dependencies.as_ref().is_some_and(RetainedHistoryRecords::terminal_is_empty){drop(self.dependencies.take());self.publish(g,metadata())?;return Ok(RetainedHistoryTransitionStep::Progress)}let mut position=self.position;let bytes=usize::try_from(scalar(source,&mut position,self.end)?).map_err(|_|fault("original transition payload exceeds platform"))?;if bytes>self.limits.maximum_binary_bytes as usize{return Err(fault("original transition payload exceeds declared binary limit"))}let end=position.checked_add(bytes).filter(|end|*end<=self.end).ok_or_else(||fault("original transition payload is truncated"))?;*self.field=Some(RetainedWireFieldDecode::new_range(source,(position,end),false)?);self.position=end;self.phase=10},
   12 if self.format==2=>return self.start_id(source,dictionary,3,13,g),12=>self.phase=13,
   _=>return Err(fault("original transition field frontier is invalid")),
  }if self.phase==13&&self.position!=self.end{return Err(fault("original transition contains trailing bytes"))}self.publish(g,metadata())?;Ok(RetainedHistoryTransitionStep::Progress)
 }
 pub fn take_ready_into(&mut self,recipient:&mut Option<HistoryTransitionRecord>,g:RetainedCloneGrant)->Result<bool,ValueError>{if !self.is_ready()||recipient.is_some()||g.maximum_items==0||g.maximum_depth==0{return Ok(false)}if self.position!=self.end{return Err(fault("original transition contains trailing bytes"))}let p=self.partial.as_ref().unwrap();if p.id.is_none()||p.actor.is_none()||p.hlt.is_none()||p.dependencies.is_none()||p.pending_dependency.is_some()||p.actor_text.is_some()||p.payload.is_none()||self.format==2&&p.observed.is_none(){return Err(fault("original transition ready recipients are incomplete"))}let mut p=self.partial.take().unwrap();*recipient=Some(HistoryTransitionRecord{id:p.id.take().unwrap(),actor:p.actor.take().unwrap(),hlt:p.hlt.unwrap(),dependencies:p.dependencies.take().unwrap(),payload:p.payload.take().unwrap(),observed:p.observed.take()});self.closed=true;self.publish(g,metadata())?;Ok(true)}
 pub fn take_fault_into(&mut self,recipient:&mut Option<ValueError>,g:RetainedCloneGrant)->Result<bool,ValueError>{if self.receipt.is_some()||recipient.is_some()||self.fault.is_none()||g.maximum_items==0||g.maximum_depth==0{return Ok(false)}*recipient=self.fault.take();self.cancel();self.publish(g,metadata())?;Ok(true)}
 pub fn cancel(&mut self){self.closing=true;if let Some(id)=self.id.as_mut(){id.cancel()}if let Some(field)=self.field.as_mut(){field.cancel()}}
 pub fn partial_is_receivable(&self)->bool{self.closing&&!self.closed&&self.fault.is_none()&&self.receipt.is_none()&&self.id.is_none()&&self.field.is_none()&&self.dependencies.is_none()&&self.partial.is_some()}
 pub fn take_partial_into(&mut self,recipient:&mut Option<RetainedHistoryTransitionPartial>,g:RetainedCloneGrant)->Result<bool,ValueError>{if !self.partial_is_receivable()||recipient.is_some()||g.maximum_items==0||g.maximum_depth==0{return Ok(false)}*recipient=self.partial.take();self.publish(g,metadata())?;Ok(true)}
 pub fn close_step<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,control:&mut dyn NativeDecodeCloseControl,g:RetainedCloneGrant)->Result<RetainedHistoryTransitionStep,ValueError>{self.validate(source,control)?;if !self.closing||self.closed||self.receipt.is_some()||self.fault.is_some(){return Ok(RetainedHistoryTransitionStep::Blocked)}let d=self.demands(source,control,g.maximum_copy_bytes)?;if !permits(g,d){return Ok(RetainedHistoryTransitionStep::Blocked)}let child=RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g};if let Some(id)=self.id.as_mut(){if id.terminal_is_empty(){drop(self.id.take());self.publish(g,metadata())?;return Ok(RetainedHistoryTransitionStep::Progress)}id.close_step(source,&[],child)?;let receipt=id.take_receipt();return self.accept(g,child,receipt)}if let Some(field)=self.field.as_mut(){if field.terminal_is_empty(){drop(self.field.take());self.publish(g,metadata())?;return Ok(RetainedHistoryTransitionStep::Progress)}field.close_step(child)?;let receipt=field.take_receipt();return self.accept(g,child,receipt)}if let Some(records)=self.dependencies.as_mut(){if records.terminal_is_empty(){drop(self.dependencies.take());self.publish(g,metadata())?;return Ok(RetainedHistoryTransitionStep::Progress)}records.take_ready_into(&mut self.partial.as_mut().unwrap().dependencies,child)?;let receipt=records.take_receipt();return self.accept(g,child,receipt)}if self.partial.is_some(){return Ok(RetainedHistoryTransitionStep::Blocked)}self.closed=true;self.publish(g,metadata())?;Ok(RetainedHistoryTransitionStep::Closed)}
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.partial.is_none()&&self.id.is_none()&&self.field.is_none()&&self.dependencies.is_none()&&self.fault.is_none()&&self.receipt.is_none()}
}
impl Drop for RetainedHistoryTransitionDecode{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"original transition abandoned native custody");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.partial);ManuallyDrop::drop(&mut self.id);ManuallyDrop::drop(&mut self.dependencies);ManuallyDrop::drop(&mut self.field);ManuallyDrop::drop(&mut self.fault)}}}}
